#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

int main(void) {
    char link[4096];
    char path[4096];
    snprintf(link, sizeof(link), "/proc/%d/exe", getpid());
    ssize_t size = readlink(link, path, sizeof(path));
    printf("link=%s size=%zd errno=%d (%s)\n",
           link, size, errno, strerror(errno));
    if (size >= 0) {
        if ((size_t)size < sizeof(path)) path[size] = 0;
        printf("path=%s\n", path);
    }
    return size >= 0 ? 0 : 1;
}

